import Foundation

/// El plan de estudio contra la fecha del ENARM (`0092`, `get_study_plan`).
///
/// **Port 1:1 de `apps/web/lib/study-plan.ts`.** No es una reimplementación: es la misma lógica
/// con los mismos casos de prueba. Si uno falla, o el port está mal o hay una divergencia real
/// con la web — en ningún caso se ajusta el test.
///
/// El cálculo entero vive en Postgres: el presupuesto, el orden y el reparto semanal. Aquí solo
/// se le da forma al jsonb y se derivan las tres decisiones que la pantalla necesita y que se
/// pueden equivocar **en silencio** — un `>=` al revés le dice "vas bien" a quien no llega.
public enum StudyPlan {

    // …

    /// La única decisión de la pantalla: qué frase dice la tarjeta del presupuesto.
    public enum Status: Sendable, Equatable {
        /// Sin fecha de examen: hay temario, no hay plan.
        case sinFecha
        /// La meta diaria cubre lo que falta.
        case alDia(requiredDailyMinutes: Int, daysToExam: Int)
        /// No alcanza: faltan `deficitMinutes` diarios sobre la meta.
        case atrasado(requiredDailyMinutes: Int, daysToExam: Int, deficitMinutes: Int)
        /// El examen ya pasó (o es hoy) y todavía queda temario.
        case sinTiempo
    }

    /// Se separa de la vista porque es la parte que puede estar mal sin que se note.
    public static func status(_ plan: Plan?) -> Status {
        guard let plan, let days = plan.daysToExam, let required = plan.requiredDailyMinutes
        else { return .sinFecha }
        if days <= 0 { return .sinTiempo }

        let deficit = required - plan.dailyGoalMinutes
        return deficit > 0
            ? .atrasado(
                requiredDailyMinutes: required, daysToExam: days, deficitMinutes: deficit)
            : .alDia(requiredDailyMinutes: required, daysToExam: days)
    }


    // …
}

import Foundation

/// Dinero en centavos enteros (igual que el backend). Nunca Double para montos.
struct Money: Hashable, Comparable, Sendable, Codable {
    var cents: Int

    init(cents: Int) { self.cents = cents }

    init(from decoder: Decoder) throws {
        cents = try decoder.singleValueContainer().decode(Int.self)
    }

    func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        try c.encode(cents)
    }

    static let zero = Money(cents: 0)
    static func + (a: Money, b: Money) -> Money { Money(cents: a.cents + b.cents) }
    static func * (a: Money, n: Int) -> Money { Money(cents: a.cents * n) }
    static func < (a: Money, b: Money) -> Bool { a.cents < b.cents }

    private static let formatter: NumberFormatter = {
        let f = NumberFormatter()
        f.numberStyle = .currency
        f.currencyCode = "MXN"
        f.locale = Locale(identifier: "es_MX")
        return f
    }()

    var formatted: String {
        let decimal = Decimal(cents) / 100
        return Money.formatter.string(from: decimal as NSDecimalNumber) ?? "$\(decimal)"
    }
}

import Foundation

/// Estima la hora del servidor a partir de `server_now` en las respuestas.
/// Solo se usa para mostrar cuentas regresivas: la regla de cierre siempre la aplica el backend.
@MainActor
@Observable
final class ServerClock {
    private(set) var offset: TimeInterval = 0
    private let localNow: () -> Date

    init(localNow: @escaping () -> Date = Date.init) {
        self.localNow = localNow
    }

    func sync(serverNow: Date) {
        offset = serverNow.timeIntervalSince(localNow())
    }

    var now: Date { localNow().addingTimeInterval(offset) }

    /// Margen de seguridad: la UI deja de ofrecer un receso unos segundos antes del cierre real.
    nonisolated static let uiSafetyMargin: TimeInterval = 30

    func isOpen(until cutoff: Date) -> Bool {
        now.addingTimeInterval(ServerClock.uiSafetyMargin) < cutoff
    }

    nonisolated static let schoolTimeZone = TimeZone(identifier: "America/Mexico_City")!
}

extension Date {
    var schoolTime: String {
        formatted(Date.FormatStyle(date: .omitted, time: .shortened, timeZone: ServerClock.schoolTimeZone)
            .locale(Locale(identifier: "es_MX")))
    }

    var schoolDateTime: String {
        formatted(Date.FormatStyle(date: .abbreviated, time: .shortened, timeZone: ServerClock.schoolTimeZone)
            .locale(Locale(identifier: "es_MX")))
    }
}
